<script setup lang="ts">
import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {useCoffee} from '../stores/coffee';import {money,stateLabels,localDate,localTime} from '../../../../packages/shared/src/domain';import type {Order} from '../../../../packages/shared/src/types';import Modal from '../../../../packages/ui/src/Modal.vue';import Icon from '../components/Icon.vue';import PaymentDialog from '../components/PaymentDialog.vue';
const s=useCoffee();const route=useRoute();const filter=ref('all');const query=ref('');const date=ref(localDate());const branch=ref('all');const selectedId=ref('');const selected=computed(()=>s.state.orders.find(o=>o.id===selectedId.value));const dialog=ref('');const payment=ref('');const reason=ref('');const refundAmount=ref(0);const split=ref<number[]>([]);const merge=ref('');const method=ref<'cash'|'transfer'>('cash');
const receipts=computed(()=>Boolean(route.meta.receipts));const sourceOrders=computed(()=>receipts.value?s.state.orders.filter(o=>o.receiptAt&&localDate(o.receiptAt)===date.value&&(branch.value==='all'||o.branchId===branch.value)):s.orders);
const orders=computed(()=>sourceOrders.value.filter(o=>(filter.value==='all'||o.state===filter.value)&&(o.number+' '+o.tableName).toLowerCase().includes(query.value.toLowerCase())));
function detail(o:Order){selectedId.value=o.id;dialog.value='detail'}
function advance(o:Order){const next=({pending:'accepted',accepted:'preparing',preparing:'ready',ready:'served',served:'completed'} as Record<string,Order['state']>)[o.state];if(next)s.run(()=>s.repo.transition(o.id,next))}
function cancel(){if(selected.value&&s.run(()=>s.repo.transition(selected.value!.id,'cancelled',reason.value)))dialog.value=''}
function refund(){if(selected.value&&s.run(()=>s.repo.refund(selected.value!.id,refundAmount.value,method.value,reason.value)))dialog.value=''}
function splitBill(){if(selected.value&&s.run(()=>s.repo.splitOrder(selected.value!.id,split.value)))dialog.value=''}
function mergeBill(){if(selected.value&&s.run(()=>s.repo.mergeBills(selected.value!.id,merge.value)))dialog.value=''}
</script><template><div class="page"><div class="page-heading"><div><h2>{{receipts?'Bill đã xuất trong ngày':'Đơn hàng'}}</h2><p>{{receipts?'Tra cứu bill, tiền đã thu và mở chi tiết để đối soát.':'Từ khách gọi món đến quầy pha chế và thanh toán.'}}</p></div><RouterLink to="/pos" class="btn primary"><Icon name="plus"/>Tạo đơn</RouterLink></div><div class="filters"><label class="search-field"><Icon name="search"/><input v-model="query" placeholder="Tìm mã đơn, bàn..." aria-label="Tìm đơn"></label><template v-if="receipts"><input type="date" v-model="date" aria-label="Ngày bill"><select v-model="branch" aria-label="Cơ sở bill"><option value="all">Tất cả cơ sở</option><option v-for="b in s.state.branches" :key="b.id" :value="b.id">{{b.name}}</option></select></template><select v-model="filter" aria-label="Trạng thái đơn"><option value="all">Tất cả trạng thái</option><option v-for="state in ['pending','accepted','preparing','ready','served','completed','cancelled']" :key="state" :value="state">{{stateLabels[state]}}</option></select></div><div class="panel table-scroll"><table class="data-table"><thead><tr><th>Mã đơn</th><th>Bàn / cơ sở</th><th>Thời gian</th><th>Tổng tiền</th><th>Đã thu</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="o in orders" :key="o.id"><td><button class="text-link strong" @click="detail(o)">{{o.number}}</button><small>{{o.lines.reduce((n,l)=>n+l.quantity,0)}} món · {{o.source==='qr'?'Khách QR':o.source==='waiter'?'Phục vụ':'Tại quầy'}}</small></td><td>{{o.tableName}}<small>{{s.state.branches.find(b=>b.id===o.branchId)?.name}}</small></td><td>{{localTime(o.createdAt)}}<small>{{localDate(o.createdAt)}}</small></td><td class="numeric">{{money(o.total)}}</td><td class="numeric">{{money(o.paid)}}</td><td><span class="status" :class="o.state">{{stateLabels[o.state]}}</span></td><td><button class="btn small outline" @click="detail(o)">Chi tiết</button></td></tr></tbody></table><div v-if="!orders.length" class="empty"><Icon name="receipt" :size="36"/><h3>Chưa có đơn phù hợp</h3><p>Đổi bộ lọc hoặc tạo đơn bán hàng mới.</p></div></div><p class="muted results-count">{{orders.length}} {{receipts?'bill':'đơn'}} · In lại không tạo thêm bill bán hàng</p></div>
<Modal v-if="dialog==='detail'&&selected" :title="selected.number+' · '+selected.tableName" wide @close="dialog=''"><div class="order-detail"><section><span class="status" :class="selected.state">{{stateLabels[selected.state]}}</span><div class="receipt-lines"><div v-for="l in selected.lines" :key="l.id"><span>{{l.quantity}} × {{l.name}}<small>{{l.variant}} · {{l.optionNames.join(', ')}} {{l.note}}</small></span><b>{{money(l.total)}}</b></div></div><div class="total-row grand-total"><strong>Tổng tiền</strong><strong>{{money(selected.total)}}</strong></div><div class="total-row"><span>Đã thu</span><b>{{money(selected.paid)}}</b></div><div class="button-grid"><button v-if="!['completed','cancelled'].includes(selected.state)" class="btn primary" @click="advance(selected)">{{({pending:'Nhận đơn',accepted:'Bắt đầu pha chế',preparing:'Món đã sẵn sàng',ready:'Đã phục vụ',served:'Hoàn tất đơn'} as Record<string,string>)[selected.state]}}</button><button class="btn outline" :disabled="!s.canCollect||selected.state==='cancelled'||selected.state==='pending'||selected.paid>=selected.total" @click="payment=selected.id;dialog=''">Thanh toán</button><RouterLink class="btn outline" :to="'/receipt/'+selected.id">Xem / in bill</RouterLink><button class="btn outline" :disabled="selected.paid>0||selected.state==='cancelled'" @click="split=selected.lines.map(()=>0);dialog='split'">Tách bill</button><button class="btn outline" :disabled="selected.paid>0||selected.state==='cancelled'" @click="merge='';dialog='merge'">Gộp bill</button><button v-if="s.canManage" class="btn outline" :disabled="selected.paid-(selected.refunded??0)<=0" @click="refundAmount=selected.paid-(selected.refunded??0);reason='';dialog='refund'">Hoàn tiền</button><button v-if="s.canManage||selected.state==='pending'" class="btn danger" :disabled="!['pending','accepted','preparing'].includes(selected.state)||selected.paid>0" @click="reason='';dialog='cancel'">Hủy đơn</button><button class="btn outline" @click="s.run(()=>s.repo.enqueuePrint(selected!.id,'bar'),'Đã lưu yêu cầu in. Chưa kết nối Print Agent.')">Phiếu pha chế</button></div></section><section class="order-timeline"><h3>Lịch sử đơn</h3><div v-for="(e,i) in selected.events" :key="i"><i></i><strong>{{stateLabels[e.state]??e.state}}</strong><small>{{localTime(e.at)}}</small><p>{{e.note}}</p></div></section></div></Modal>
<Modal v-if="dialog==='cancel'&&selected" title="Hủy đơn" @close="dialog=''"><label class="field"><span>Lý do hủy</span><textarea v-model="reason" maxlength="300"></textarea></label><button class="btn danger full" :disabled="!reason.trim()" @click="cancel">Xác nhận hủy</button></Modal>
<Modal v-if="dialog==='refund'&&selected" title="Hoàn tiền" @close="dialog=''"><label class="field"><span>Số tiền hoàn</span><input type="number" min="1" :max="selected.paid-(selected.refunded??0)" v-model.number="refundAmount"></label><label class="field"><span>Phương thức hoàn</span><select v-model="method"><option value="cash">Tiền mặt</option><option value="transfer">Chuyển khoản</option></select></label><label class="field"><span>Lý do</span><textarea v-model="reason"></textarea></label><p class="muted small-copy">Chỉ lưu bản ghi hoàn tiền trên trình duyệt; chưa chuyển tiền.</p><button class="btn primary full" :disabled="!reason.trim()" @click="refund">Lưu bản ghi hoàn tiền</button></Modal>
<Modal v-if="dialog==='split'&&selected" title="Tách bill theo số lượng món" @close="dialog=''"><label v-for="(l,i) in selected.lines" :key="l.id" class="check-row"><span>{{l.name}} ({{l.quantity}})</span><input type="number" min="0" :max="l.quantity" v-model.number="split[i]"></label><p class="muted">Chọn số lượng chuyển sang bill mới. Tổng tiền được giữ nguyên.</p><button class="btn primary full" @click="splitBill">Tách bill</button></Modal>
<Modal v-if="dialog==='merge'&&selected" title="Gộp bill" @close="dialog=''"><label class="field"><span>Bill cần gộp vào đơn hiện tại</span><select v-model="merge"><option value="">Chọn bill</option><option v-for="o in s.orders.filter(o=>o.id!==selected!.id&&!o.paid&&!['completed','cancelled'].includes(o.state))" :key="o.id" :value="o.id">{{o.number}} · {{money(o.total)}}</option></select></label><button class="btn primary full" :disabled="!merge" @click="mergeBill">Gộp bill</button></Modal><PaymentDialog v-if="payment" :order-id="payment" @close="payment=''"/></template>
